/*
    "Starship" by @XorDev
    (Debug viz tweak by @unconed)

    Inspired by the debris from SpaceX's 7th Starship test:
    https://x.com/elonmusk/status/1880040599761596689

    My original twigl version:
    https://x.com/XorDev/status/1880344887033569682
*/
void mainImage( out vec4 O, vec2 I)
{
    //Resolution for scaling
    vec2 r=iResolution.xy;

    //(Debug) Vis step
    float s = max(0., floor((I.x*1.2-I.y/2.)/r.x * 5. + 1.0));

    //Center, rotate and scale
    vec2 p=(I+I-r)/r.y*mat2(4,-3,3,4);
    //Clear fragColor
    O*=0.;

    vec4 c;
    //Iterate through 50 particles
    for(float t=iTime,i,j; i++<50.0;
        j = floor(fract(t / 20.0) * 10.0),

        //Set color
        O += (s > 3. ? 1.0 : float(i == j)) * (
            s > 0. ? cos(sin(i) * vec4(1,2,3,0)) + 1. : vec4(1.)
        )
        //Flashing brightness
        * (s > 2. ? exp(sin(i+i*t*.1)) : 1.)
        //Trail particles with attenuating light
        / (s > 1. ? length(max(p,
            //Stretch the x axis with noise and smear y axis a little
            p/vec2(texture(iChannel0,p/exp(sin(i)+5.)+vec2(t/8.,i)).r*40.,2))
        ) : length(vec2(texture(iChannel0,p/exp(sin(i)+5.)+vec2(t/8.,i)).r*40.,2)))
    )
        //Shift position for each particle
        p+=2.*cos(i*i+t*.2+p.x*.02+i*vec2(11,9));

    //Add sky background and "tanh" tonemap
    if (s > 3.) O=tanh(.01*p.y*vec4(0,1,2,3)+O*O/1e4);
    else if (s > 2.) O *= 1e-1;
    else if (s > 1.) O *= 1e-1;
    else O *= 2.;
}
